package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create-owner request that is missing or blank in any required field
 * ({@code firstName}, {@code lastName}, {@code address}, {@code city}, {@code telephone}).
 *
 * <p>Runs first in the {@code POST /api/owners} pipeline and binds the body without
 * {@code @Valid}, so a missing field surfaces as a {@link MissingOwnerFieldsException}
 * (400 with an {@code errors} array) rather than the generic schema-validation response.
 * The {@code address} is normalized first (see {@link AddressNormalizer}) so the blank
 * check rejects an address that is empty after normalization. It then normalizes the
 * telephone to E.164 form (see {@link TelephoneE164}), rejecting with an
 * {@link InvalidTelephoneException} (400) when it cannot form a valid E.164 number.
 * On success it stores the normalized address and E.164 telephone and republishes the
 * body for {@link BuildOwner}.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
        List<String> errors = new ArrayList<>();
        String address = AddressNormalizer.normalize(request.getAddress());
        if (isBlank(request.getFirstName())) {
            errors.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            errors.add("lastName");
        }
        if (isBlank(address)) {
            errors.add("address");
        }
        if (isBlank(request.getCity())) {
            errors.add("city");
        }
        if (isBlank(request.getTelephone())) {
            errors.add("telephone");
        }
        if (!errors.isEmpty()) {
            throw new MissingOwnerFieldsException(errors);
        }
        request.setAddress(address);
        String telephone = TelephoneE164.normalize(request.getTelephone());
        if (telephone == null) {
            throw new InvalidTelephoneException(
                    "Telephone cannot be normalized to a valid E.164 number");
        }
        request.setTelephone(telephone);
        request.setEmail(OwnerEmail.normalize(request.getEmail()));
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
 * where {@code CITY3} is the upper-cased first three letters of {@code city},
 * {@code LAST3} the upper-cased first three letters of {@code lastName} and
 * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the
 * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
 *
 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner} in the
 * {@code POST /api/owners} pipeline, so the count it reads excludes the owner being
 * created; the code is then persisted with the new owner and returned by later reads.
 * It mutates the built {@link Owner} in place (see {@code @Val} semantics).
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        long inCity = ownerRepository.findAll().stream()
            .filter(existing -> city == null
                ? existing.getCity() == null
                : city.equalsIgnoreCase(existing.getCity()))
            .count();
        long sequence = inCity + 1;
        owner.setCustomerCode(
            String.format("%s-%s-%04d", first3(city), first3(owner.getLastName()), sequence));
    }

    private static String first3(String value) {
        String prefix = value == null ? "" : value;
        return prefix.substring(0, Math.min(3, prefix.length())).toUpperCase();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share
 * the same {@code firstName} and {@code lastName}, compared case-insensitively.
 *
 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
 * {@link SaveOwner} in the {@code POST /api/owners} pipeline, so the count it reads
 * excludes the owner being created; the value is then persisted with the new owner and
 * returned by later reads. It mutates the built {@link Owner} in place (see
 * {@code @Val} semantics).
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

